/*
 * bluetoothturbo_i18n.c - translation lookup for the "Bluetooth Turbo" Settings page.
 * The strings are in bluetoothturbo_i18n_table.h, generated by tools/gen_i18n.py
 * (UTF-8; English is authoritative, the other 19 languages are machine
 * translations that native speakers are welcome to correct).
 *
 * Same functions as Wi-Fi Turbo's: the language comes from the
 * /CONFIG/SYSTEM/language registry key (no init gate in the Settings app),
 * with sceAppUtilSystemParamGetInt as a fallback, and English(US) otherwise.
 * Stubs (weak, both resident in NPXS10015): SceRegistryMgr, SceAppUtil.
 */
#include "bluetoothturbo_i18n.h"

extern int sceRegMgrGetKeyInt(const char *category, const char *name, int *value);
extern int sceAppUtilSystemParamGetInt(int paramId, int *value);

#define BTT_SYSTEM_PARAM_ID_LANG 1

#include "bluetoothturbo_i18n_table.h"

/* ---- language detection ------------------------------------------------ */

int btt_i18n_lang(void)
{
	int lang = -1;

	/* Primary (reliable for NPXS10015): the system registry. SceSettings
	 * already links RegMgr; /CONFIG/SYSTEM/language is the canonical store and
	 * has no init gate. */
	if (sceRegMgrGetKeyInt("/CONFIG/SYSTEM", "language", &lang) >= 0 &&
	    lang >= 0 && lang < BTT_LANG_COUNT)
		return lang;

	/* Fallback: SDK system param. Only works once the host app has called
	 * sceAppUtilInit(); otherwise returns SCE_APPUTIL_ERROR_NOT_INITIALIZED. */
	lang = -1;
	if (sceAppUtilSystemParamGetInt(BTT_SYSTEM_PARAM_ID_LANG, &lang) >= 0 &&
	    lang >= 0 && lang < BTT_LANG_COUNT)
		return lang;

	return BTT_LANG_ENGLISH_US;
}

/* ---- lookup ------------------------------------------------------------ */

const char *btt_i18n_for(int id, int lang)
{
	const char *s;

	if (id < 0 || id >= BTT_I18N_COUNT)
		return "";
	if (lang < 0 || lang >= BTT_LANG_COUNT)
		lang = BTT_LANG_ENGLISH_US;

	s = g_tbl[id][lang];
	if (s == 0)
		s = g_tbl[id][BTT_LANG_ENGLISH_US];   /* fallback */
	if (s == 0)
		s = "";
	return s;
}

const char *btt_i18n(int id)
{
	return btt_i18n_for(id, btt_i18n_lang());
}

/* ---- UTF-8 -> UTF-16 decoder ------------------------------------------- */

int btt_i18n_to_u16(const char *utf8, unsigned short *out, int out_max)
{
	const unsigned char *s = (const unsigned char *)utf8;
	int n = 0;

	if (out == 0 || out_max <= 0)
		return 0;
	if (s == 0) {
		out[0] = 0;
		return 0;
	}

	while (*s) {
		unsigned int cp;
		unsigned char c = *s;

		if (c < 0x80) {                         /* 1 byte: ASCII */
			cp = c;
			s += 1;
		} else if ((c & 0xE0) == 0xC0) {        /* 2 bytes */
			if ((s[1] & 0xC0) != 0x80) { s += 1; continue; }
			cp = ((unsigned int)(c & 0x1F) << 6) |
			     (unsigned int)(s[1] & 0x3F);
			s += 2;
		} else if ((c & 0xF0) == 0xE0) {        /* 3 bytes (BMP) */
			if ((s[1] & 0xC0) != 0x80 || (s[2] & 0xC0) != 0x80) {
				s += 1;
				continue;
			}
			cp = ((unsigned int)(c & 0x0F) << 12) |
			     ((unsigned int)(s[1] & 0x3F) << 6) |
			     (unsigned int)(s[2] & 0x3F);
			s += 3;
		} else if ((c & 0xF8) == 0xF0) {        /* 4 bytes: astral - skip */
			if ((s[1] & 0xC0) != 0x80 || (s[2] & 0xC0) != 0x80 ||
			    (s[3] & 0xC0) != 0x80) {
				s += 1;
				continue;
			}
			s += 4;                 /* best-effort: drop (needs surrogates) */
			continue;
		} else {                                /* stray continuation / invalid */
			s += 1;
			continue;
		}

		if (cp == 0)
			break;
		if (n >= out_max - 1)                   /* leave room for NUL */
			break;
		out[n++] = (unsigned short)cp;
	}

	out[n] = 0;
	return n;
}
